pub fn prepare_buffers() {
    let wanted = training_mod_macros_max_frames();
    CAPTURE.prepare(wanted);
    let grow = lock_read(&MOTION).play.capacity() < wanted;
    if !grow { return; }
    let mut play = Vec::with_capacity(wanted);
    {
